;const hiddenInput=document.getElementById('selectedDeptInput');if(hiddenInput)hiddenInput.value=deptName;}function togglePasswordInput(inputId,iconId){const el=document.getElementById(inputId);const icon=document.getElementById(iconId);if(!el||!icon)return;if(el.type==='password'){el.type='text';icon.textContent='visibility_off';}else{el.type='password';icon.textContent='visibility';}}function submitRegistration(e){e.preventDefault();const alertBox=document.getElementById('regSuccessAlert');if(alertBox){alertBox.classList.remove('hidden');}}function checkTracking(){alert('Tracking DSAM-DEPT-104: Application Stage 3/4 — Awaiting GM Mr. Sonny Mata Authorization.');}</script></div></main>

